        require(buyer == address(0), "sold");
        uint256 p = price();
        require(msg.value >= p, "underpaid");
        buyer = msg.sender;
        payable(seller).transfer(p);
        if (msg.value > p) payable(msg.sender).transfer(msg.value - p);
    }
}
